const char *project_name="m8051";
const char *project_file="m8051.ac";
const char *archc_version="2.4.1";
const char *archc_options="-nw -nci ";

#include  <iostream>
#include  <systemc.h>
#include  "ac_stats_base.H"
#include  "m8051.H"



int sc_main(int ac, char *av[])
{

  //!  ISA simulator
  m8051 m8051_proc1("m8051");

#ifdef AC_DEBUG
  ac_trace("m8051_proc1.trace");
#endif 

  m8051_proc1.init(ac, av);
  m8051_proc1.set_prog_args();
  cerr << endl;

  sc_start();

  m8051_proc1.PrintStat();
  cerr << endl;

#ifdef AC_STATS
  ac_stats_base::print_all_stats(std::cerr);
#endif 

#ifdef AC_DEBUG
  ac_close_trace();
#endif 

  return m8051_proc1.ac_exit_status;
}
